    "effectZh": "[登场时]\n查看自己山札上方的 3 张卡牌。从中公开最多 1 张［特征：第 104 期兵］并加入手牌，其余按任意顺序置于山札下方。若将卡加入手牌，则将自己手牌的 1 张置入场外。",
