    "effect": "[インパクト無効]\n（このキャラとバトルをしたキャラはこのバトル中、\n[インパクト]\nを失う）\n[起動メイン]\n[ターン1]\n自分のライフエリアにあるカードを1枚手札に加える。そうした場合、このキャラはこのターン中、\n[インパクト（1）]\nを得る。\n[アタック時]\n『自分の山札の上から1枚見て、見たカードが必要エナジーが3以下の［特徴：104期兵］の場合、公開し手札に加えてもよい。手札に加えない場合、そのカードを山札の上か下に置く』。自分のライフが3以下の場合、『カードを1枚引く』に代わる。",
    "effectZh": "[冲击无效化]\n(与此卡进行战斗的卡牌在本场战斗中，\n[冲击]\n失效)\n[启动主]\n[回合 1]\n将自己生命区域中的 1 张卡牌加入手牌。若如此操作，此卡本回合获得\n[冲击 (1)]。\n[攻击时]\n『查看自己山札上方的 1 张卡牌，若看到的卡牌必要能量为 3 以下的［特征：第 104 期兵］，可公开并加入手牌。若不加入手牌，将该卡置于山札上方或下方』。当自己的生命值为 3 以下时，『抽1张牌』替代之。",
    "trigger": "[アクティブ]\n自分の場のキャラを1枚選び、アクティブにし、このターン中、BP+3000。",
